changeSet.sql:

CREATE or ALTER FUNCTION [api].[ShouldAllowNewBatchCall]
(    
)
RETURNS bit
AS
BEGIN    
	declare @runAssetCount int = 0;
	declare @runAssetDeleteCount int = 0;
	declare @runRelationshipCount int = 0;
	declare @runAssetTypeDeleteCount int =0;
	-- never ran a batch api execution
	if ( not exists (select count(1) from api.execution))
	begin
		return 1;
	end

	-- all jobs have completed
	if ( not exists (select count(1) from api.execution where completedOn is null))
	begin
		return 1;
	end

	-- all the jobs that have not completed are older than 24 hours
	-- all jobs have completed
	if ( not exists (select count(1) from api.execution where completedOn is null and startedon > DATEADD(day, -1, GETDATE()) ) )
	begin
		return 1;
	end

	-- count of running asset batch jobs is > 1 for past 24 hours
	select @runAssetCount = count(1) from api.execution e inner join api.ExecutionAsset ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE()) and e.ErrorMessage is null

	if ( @runAssetCount > 1 )
	begin
		return 0;
	end

	-- count of running asset delete batch jobs is > 1 for past 24 hours
	select @runAssetDeleteCount = count(1) from api.execution e inner join api.ExecutionDeletedAsset ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE()) and e.ErrorMessage is null

	if ( @runAssetDeleteCount > 1 )
	begin
		return 0;
	end

	-- count of running asset delete batch jobs is > 1 for past 24 hours
	select @runRelationshipCount = count(1) from api.execution e inner join api.ExecutionRelationship ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE())  and e.ErrorMessage is null

	if ( @runRelationshipCount > 1 )
	begin
		return 0;
	end

	-- count of running asset delete batch jobs is > 1 for past 24 hours
	select @runAssetTypeDeleteCount = count(1) from api.execution e inner join api.executiondeletedassettype ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE())  and e.ErrorMessage is null

	if ( @runAssetTypeDeleteCount > 1 )
	begin
		return 0;
	end

	-- some combination of the 3 types of batch jobs running more than 1 instance already
	if ((@runAssetCount + @runAssetDeleteCount + @runRelationshipCount + @runAssetTypeDeleteCount) > 1)
	begin
		return 0;
	end

    -- Return the result of the function
    RETURN 1;
END
